/* Demo media and administration. Images are persisted in this browser's IndexedDB. */
const icon=(name,cls='')=>{const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',bag:'M5 7h14l1 14H4L5 7Zm3 1V6a4 4 0 0 1 8 0v2',box:'m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v10M7.5 5l9 4',image:'M3 3h18v18H3V3Zm0 14 5-5 4 4 4-6 5 7M8 7h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',arrow:'M19 12H5m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',edit:'m4 16 12-12 4 4L8 20H4v-4Zm9-9 4 4',orders:'M5 3h14v18H5V3Zm4 5h6m-6 4h6m-6 4h3',wallet:'M3 5h17v15H3V5Zm0 4h18v7h-6V9',check:'m5 12 4 4L19 6',upload:'M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5',close:'m6 6 12 12M6 18 18 6'};return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`};
let media={},mediaDb=null,mediaStorageError=false,mediaDraft=null,editingMediaKey='',mediaTab='all',selectedGallery=0,adminQuery='',orderFilter='all',adminPeriod='all';
const defaultImage=(key)=>{let beige=key==='category-beige'||(/^product-/.test(key)&&products.find(p=>'product-'+p.id===key)?.category==='beige');return {src:beige?'assets/beige-v2.png':'assets/black-v2.png',x:50,y:0,zoom:1,fit:'cover',alt:beige?'عباية بيج بتصميم انسيابي':'عباية سوداء بتطريز ناعم'}};
const imageConfig=key=>({...defaultImage(key),...(media[key]||{})});
const imageStyle=c=>`object-fit:${c.fit==='contain'?'contain':'cover'};object-position:${c.x}% ${c.y}%;transform:scale(${c.zoom});transform-origin:${c.x}% ${c.y}%`;
function mediaImage(key,alt='',extra=''){const c=imageConfig(key);return `<img data-image-slot="${esc(key)}" src="${esc(c.src)}" alt="${esc(c.alt||alt)}" style="${imageStyle(c)}" ${extra} loading="lazy">`}
function productGallery(p){const keys=['product-'+p.id,...(p.gallery||[])];selectedGallery=Math.min(selectedGallery,keys.length-1);return `<div class="product-gallery"><div class="gallery-main">${mediaImage(keys[selectedGallery],p.name)}</div>${keys.length>1?`<div class="gallery-thumbs">${keys.map((key,i)=>`<button class="${i===selectedGallery?'selected':''}" aria-label="عرض الصورة ${i+1}" onclick="selectedGallery=${i};render(false)">${mediaImage(key,p.name)}</button>`).join('')}</div>`:''}</div>`}
function openMediaDb(){return new Promise(resolve=>{const req=indexedDB.open('abayat-media-v2',1);req.onupgradeneeded=()=>req.result.createObjectStore('settings');req.onerror=()=>{mediaStorageError=true;resolve()};req.onsuccess=()=>{mediaDb=req.result;const get=mediaDb.transaction('settings').objectStore('settings').get('images');get.onsuccess=()=>{media=get.result||{};resolve()};get.onerror=()=>{mediaStorageError=true;resolve()}}})}
function persistMedia(next){return new Promise((resolve,reject)=>{if(!mediaDb)return reject(new Error('تعذر حفظ الصور في هذا المتصفح'));const tx=mediaDb.transaction('settings','readwrite');tx.objectStore('settings').put(next,'images');tx.oncomplete=()=>{media=next;resolve()};tx.onerror=()=>reject(new Error('المساحة المتاحة لا تكفي لحفظ الصورة. جرّبي صورة أصغر.'));tx.onabort=()=>reject(new Error('لم يتم الحفظ. جرّبي مرة أخرى.'))})}
let imageSlots=()=>[{key:'hero',title:'البانر الرئيسي',type:'site',note:'واجهة المتجر',ratio:'wide'},{key:'category-black',title:'تصنيف العبايات السوداء',type:'site',note:'بطاقة التشكيلة',ratio:'wide'},{key:'category-beige',title:'تصنيف الألوان الهادئة',type:'site',note:'بطاقة التشكيلة',ratio:'wide'},{key:'admin-promo',title:'صورة لوحة الإدارة',type:'site',note:'البطاقة الجانبية',ratio:'wide'},...products.flatMap(p=>[{key:'product-'+p.id,title:p.name,type:'product',note:'الصورة الرئيسية',ratio:'portrait',product:p.id},...(p.gallery||[]).map((key,i)=>({key,title:p.name+' · '+(i+2),type:'product',note:'صورة إضافية',ratio:'portrait',product:p.id}))])];
function mediaPage(){const slots=imageSlots().filter(s=>(mediaTab==='all'||s.type===mediaTab)&&[s.title,s.note].some(v=>v.includes(adminQuery.trim())));const paged=paginate(slots,'media');return `<div class="page-title"><div><h1>مكتبة الصور</h1><p>كل صور متجرك… تحت تحكمك.</p></div><span class="small-chip">${slots.length} صور</span></div><div class="media-banner">${icon('image')}<div><strong>اختاري الصورة واضبطيها على ذوقك</strong><p>ارفعي صورة جديدة، حددي نقطة التركيز، وغيّري التكبير وطريقة العرض. التعديل يظهر في معاينة مباشرة.</p></div></div><div class="filter-tabs">${[['all','كل الصور'],['site','واجهة المتجر'],['product','صور المنتجات']].map(([id,title])=>`<button class="${mediaTab===id?'active':''}" onclick="mediaTab='${id}';render(false)">${title}</button>`).join('')}</div><div class="media-grid">${paged.items.map(s=>`<article class="media-card"><div class="media-card-image ${s.ratio}">${mediaImage(s.key,s.title)}<button class="image-edit-bubble" aria-label="تعديل ${esc(s.title)}" onclick="editImage('${s.key}')">${icon('edit')}</button></div><div class="media-card-info"><small>${s.note}</small><h3>${esc(s.title)}</h3><button class="text-button" onclick="editImage('${s.key}')">التحكم في الصورة ${icon('arrow')}</button></div></article>`).join('')}</div>${paged.controls}${!slots.length?'<div class="empty">لا توجد صور مطابقة للبحث.</div>':''}<div class="storage-note">الصور والتغييرات محفوظة في هذا المتصفح فقط ضمن الديمو.</div>`}
function editImage(key){editingMediaKey=key;mediaDraft={...imageConfig(key)};const slot=imageSlots().find(s=>s.key===key);const title=slot?.title||'صورة المنتج';$('#modal')?.remove();let d=document.createElement('dialog');d.id='modal';d.className='media-dialog';d.innerHTML=`<div class="dialog-header"><div><small>إدارة الصور</small><h2>${esc(title)}</h2></div><button class="icon-button" aria-label="إغلاق" onclick="this.closest('dialog').close()">${icon('close')}</button></div><div class="image-editor"><div><div id="imagePreview" class="image-preview ${slot?.ratio==='wide'?'wide':'portrait'}">${mediaImage(key,title)}</div><p class="preview-caption">معاينة مباشرة · التغييرات لا تُعتمد إلا بعد الحفظ</p></div><form id="imageForm" onsubmit="saveImage(event)"><label class="upload-area">${icon('upload')}<strong>تغيير الصورة</strong><span>JPG أو PNG أو WebP · حتى ١٠ ميجابايت</span><input type="file" id="imageUpload" accept="image/jpeg,image/png,image/webp" onchange="uploadImage(this)"></label><p id="uploadMessage" class="muted" role="status"></p><label class="field">وصف الصورة<input name="alt" value="${esc(mediaDraft.alt)}" oninput="mediaDraft.alt=this.value;refreshImagePreview()" maxlength="150"></label><label class="field">طريقة العرض<select name="fit" onchange="mediaDraft.fit=this.value;refreshImagePreview()"><option value="cover" ${mediaDraft.fit==='cover'?'selected':''}>ملء المساحة</option><option value="contain" ${mediaDraft.fit==='contain'?'selected':''}>إظهار الصورة كاملة</option></select></label><label class="range-field">موضع الصورة أفقيًا <output id="xValue">${mediaDraft.x}%</output><input name="x" type="range" min="0" max="100" value="${mediaDraft.x}" oninput="changeImageControl('x',this.value)"></label><label class="range-field">موضع الصورة رأسيًا <output id="yValue">${mediaDraft.y}%</output><input name="y" type="range" min="0" max="100" value="${mediaDraft.y}" oninput="changeImageControl('y',this.value)"></label><label class="range-field">التكبير <output id="zoomValue">${Math.round(mediaDraft.zoom*100)}%</output><input name="zoom" type="range" min="1" max="2.5" step="0.05" value="${mediaDraft.zoom}" oninput="changeImageControl('zoom',this.value)"></label><div class="editor-buttons"><button class="button" id="saveImageButton" type="submit">${icon('check')} حفظ الصورة</button><button class="button outline" type="button" onclick="resetImageDraft()">استعادة الأصل</button></div><p class="editor-error" id="imageError" role="alert"></p></form></div>`;document.body.append(d);d.showModal()}
function refreshImagePreview(){const img=$('#imagePreview img');if(img){img.src=mediaDraft.src;img.alt=mediaDraft.alt;img.style.cssText=imageStyle(mediaDraft)}}
function changeImageControl(k,v){mediaDraft[k]=Number(v);$('#'+k+'Value').textContent=Math.round((k==='zoom'?100:1)*v)+'%';refreshImagePreview()}
function resetImageDraft(){mediaDraft=defaultImage(editingMediaKey);const f=$('#imageForm');for(const k of ['x','y','zoom','fit','alt'])f.elements[k].value=mediaDraft[k];for(const k of ['x','y','zoom'])changeImageControl(k,mediaDraft[k]);$('#uploadMessage').textContent='تمت استعادة الصورة الأصلية في المعاينة. اضغطي حفظ لاعتمادها.';refreshImagePreview()}
async function decodeImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('اختاري ملف JPG أو PNG أو WebP.');if(file.size>10*1024*1024)throw new Error('الحد الأقصى لحجم الصورة ١٠ ميجابايت.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('تعذر قراءة الصورة. جرّبي ملفًا آخر.'));i.src=url});const scale=Math.min(1,1400/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#f6f2eb';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.88)}finally{URL.revokeObjectURL(url)}}
async function uploadImage(input){const file=input.files[0];if(!file)return;const form=$('#imageForm'),dialog=$('#modal'),button=$('#saveImageButton');const request=Symbol();form.uploadRequest=request;button.disabled=true;$('#imageError').textContent='';try{const src=await decodeImage(file);if(!dialog.open||$('#imageForm')!==form||form.uploadRequest!==request)return;mediaDraft={...mediaDraft,src,x:50,y:0,zoom:1};for(const k of ['x','y','zoom']){form.elements[k].value=mediaDraft[k];changeImageControl(k,mediaDraft[k])}$('#uploadMessage').textContent='جاهزة للمعاينة: '+file.name;refreshImagePreview()}catch(e){if($('#imageForm')===form)$('#imageError').textContent=e.message}finally{if(form.uploadRequest===request)button.disabled=false}}
async function saveImage(e){e.preventDefault();const button=$('#saveImageButton'),dialog=$('#modal');button.disabled=true;try{await persistMedia({...media,[editingMediaKey]:{...mediaDraft}});dialog.close();render(false);toast('تم حفظ الصورة وتحديث كل أماكن ظهورها')}catch(e){if(dialog.open)dialog.querySelector('#imageError').textContent=e.message;else toast(e.message)}finally{button.disabled=false}}
function manageGallery(id){const p=products.find(x=>x.id===id);const keys=['product-'+id,...(p.gallery||[])];modal(`<h2>صور ${esc(p.name)}</h2><p class="muted">الصورة الأولى تظهر في بطاقات المنتج والسلة. الصور الإضافية تظهر في صفحة المنتج.</p><div class="gallery-manager">${keys.map((key,i)=>`<div><div class="gallery-manager-img">${mediaImage(key,p.name)}</div><small>${i===0?'الصورة الرئيسية':'صورة إضافية '+i}</small><button class="text-button" onclick="editImage('${key}')">تعديل الصورة</button>${i?`<button class="text-button" onclick="makeMainImage(${id},'${key}')">تعيين رئيسية</button><button class="text-button danger" onclick="removeGalleryImage(${id},'${key}')">إزالة من المعرض</button>`:''}</div>`).join('')}</div>${keys.length<6?`<label class="button outline">${icon('plus')} إضافة صورة للمعرض<input type="file" class="hidden-file" accept="image/jpeg,image/png,image/webp" onchange="addGalleryImage(${id},this)"></label>`:'<p>المعرض يحتوي على الحد الأقصى: ٦ صور.</p>'}<p class="muted" id="galleryMessage" role="status"></p>`);$('#modal').classList.add('gallery-dialog')}
async function addGalleryImage(id,input){try{const file=input.files[0];if(!file)return;input.disabled=true;$('#galleryMessage').textContent='جاري تجهيز الصورة…';const src=await decodeImage(file);const key='gallery-'+id+'-'+Date.now();await persistMedia({...media,[key]:{src,x:50,y:50,zoom:1,fit:'cover',alt:products.find(p=>p.id===id).name}});const p=products.find(p=>p.id===id);p.gallery=[...(p.gallery||[]),key];save();manageGallery(id);toast('تمت إضافة الصورة للمعرض')}catch(e){if($('#galleryMessage'))$('#galleryMessage').textContent=e.message;else toast(e.message);input.disabled=false}}
async function makeMainImage(id,key){try{const main='product-'+id;await persistMedia({...media,[main]:imageConfig(key),[key]:imageConfig(main)});manageGallery(id);render(false);toast('تم تغيير الصورة الرئيسية')}catch(e){toast(e.message)}}
function removeGalleryImage(id,key){const p=products.find(p=>p.id===id);p.gallery=(p.gallery||[]).filter(k=>k!==key);save();manageGallery(id);render(false);toast('تمت إزالة الصورة من المعرض')}
const shownOrders=()=>orders.filter(o=>(orderFilter==='all'||o.status===orderFilter)&&[o.id,o.name,o.phone,o.city].some(v=>String(v).includes(adminQuery))&&(adminPeriod==='all'||Date.now()-(o.createdAt||Number(o.id?.startsWith('ABY-')?Date.now():0))<Number(adminPeriod)*86400000));
function inventoryTable(limit){const list=products.filter(p=>p.name.includes(adminQuery));const paged=paginate(list,'products',20);const selected=limit?list.slice(0,limit):paged.items;return `<div class="table-wrap"><table class="inventory-table"><thead><tr><th>المنتج</th><th>رقم المنتج</th><th>السعر</th><th>المخزون</th><th>الحالة</th><th>المقاسات</th><th>إدارة</th></tr></thead><tbody>${selected.map(p=>`<tr><td><a class="table-product" href="#product/${p.id}"><span class="table-thumb">${mediaImage('product-'+p.id,p.name)}</span><strong>${esc(p.name)}</strong></a></td><td class="ltr">ABY-${String(p.id).slice(-4).padStart(4,'0')}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><span class="status ${p.stock===0?'cancelled':p.stock<10?'low':'completed'}">${p.stock===0?'غير متوفر':p.stock<10?'منخفض':'متوفر'}</span></td><td><span class="size-chips">${productSizes(p).map(s=>`<i>${esc(s)}</i>`).join('')}</span></td><td><div class="table-actions"><button class="icon-button" aria-label="تعديل ${esc(p.name)}" onclick="editProduct(${p.id})">${icon('edit')}</button><button class="icon-button" aria-label="صور ${esc(p.name)}" onclick="manageGallery(${p.id})">${icon('image')}</button></div></td></tr>`).join('')}</tbody></table>${!selected.length?'<div class="empty">لا توجد منتجات مطابقة للبحث.</div>':''}${limit?'':paged.controls}</div>`}
function orderBadge(s){return {جديد:'new','جاري التجهيز':'preparing','تم الشحن':'shipped',مكتمل:'completed',ملغي:'cancelled'}[s]||''}
function adminOrdersTable(limit){const list=shownOrders(),paged=paginate(list,'admin-orders',20),selected=limit?list.slice(0,limit):paged.items;return selected.length?`<div class="table-wrap"><table><thead><tr><th>رقم الطلب</th><th>العميل</th><th>الحالة</th><th>الإجمالي</th><th>التاريخ</th><th>التفاصيل</th></tr></thead><tbody>${selected.map(o=>`<tr><td class="ltr">${o.id}</td><td>${esc(o.name)}</td><td><select class="status-select ${orderBadge(o.status)}" aria-label="حالة الطلب ${o.id}" onchange="setStatus('${o.id}',this.value)">${statuses.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${money(o.total)}</td><td>${esc(o.date)}</td><td><button class="icon-button" aria-label="عرض ${o.id}" onclick="showOrder('${o.id}')">${icon('orders')}</button></td></tr>`).join('')}</tbody></table></div>${limit?'':paged.controls}`:`<div class="dashboard-empty">${icon('orders')}<h3>${orders.length?'لا توجد طلبات مطابقة':'أول طلب… بداية الحكاية'}</h3><p>${orders.length?'جرّبي تغيير البحث أو الحالة.':'أضيفي بيانات عرض لتجربة لوحة الإدارة أو أنشئي طلبًا من المتجر.'}</p>${!orders.length?'<button class="button" onclick="addSampleOrders()">إضافة طلبات تجريبية</button>':''}</div>`}
function statsCards(){const filtered=shownOrders(),active=filtered.filter(o=>o.status!=='ملغي');return `<div class="dashboard-stats">${[['إجمالي المبيعات',money(active.reduce((s,o)=>s+o.total,0)),'wallet','olive','قيمة الطلبات غير الملغاة'],['الطلبات الجديدة',filtered.filter(o=>o.status==='جديد').length,'box','sand','طلبات تنتظر المراجعة'],['إجمالي الطلبات',filtered.length,'orders','sand','خلال الفترة المحددة'],['المنتجات',products.length,'bag','olive','منتجات في التشكيلة']].map(([title,value,ico,color,note])=>`<div class="metric"><div><span>${title}</span><strong>${value}</strong><small>${note}</small></div><span class="metric-icon ${color}">${icon(ico)}</span></div>`).join('')}</div>`}
function admin(tab){let body='';const periodSelect=`<select class="period-select" aria-label="الفترة" onchange="adminPeriod=this.value;render(false)">${[['all','كل الفترات'],['30','آخر ٣٠ يومًا'],['7','آخر ٧ أيام']].map(([v,t])=>`<option value="${v}" ${adminPeriod===v?'selected':''}>${t}</option>`).join('')}</select>`;if(tab==='catalogue')body=catalogueAdminPage();else if(tab==='clients')body=clientsAdminPage();else if(tab==='media')body=mediaPage();else if(tab==='products')body=`<div class="page-title"><div><h1>المنتجات والمخزون</h1><p>تفاصيل كل قطعة، وصورها، وكمياتها.</p></div><button class="button" onclick="editProduct()">${icon('plus')} إضافة منتج</button></div><div class="dashboard-panel">${inventoryTable()}</div>`;else if(tab==='orders')body=`<div class="page-title"><div><h1>إدارة الطلبات</h1><p>من تأكيد الطلب، حتى التسليم.</p></div>${periodSelect}</div><div class="filter-tabs">${['all',...statuses].map(s=>`<button class="${s===orderFilter?'active':''}" onclick="orderFilter='${s}';render(false)">${s==='all'?'كل الطلبات':s}</button>`).join('')}</div><div class="dashboard-panel">${adminOrdersTable()}</div>`;else if(tab==='settings')body=`<div class="page-title"><div><h1>إعدادات المتجر</h1><p>هوية متجرك ووسائل التواصل.</p></div></div><form class="dashboard-panel settings-form" onsubmit="updateSettings(event)"><label class="field">اسم المتجر<input name="name" value="${esc(settings.name)}" required></label><label class="field">رقم التواصل<input name="phone" value="${esc(settings.phone)}"></label><label class="field">البريد الإلكتروني<input name="email" type="email" value="${esc(settings.email)}"></label><button class="button">حفظ الإعدادات</button><a href="#admin/media" class="button outline">إدارة صور المتجر</a></form>`;else body=`<div class="page-title"><div><h1>مرحبًا بك في لوحة إدارة المتجر</h1><p>إليك نظرة عامة على أداء متجرك اليوم.</p></div>${periodSelect}</div>${statsCards()}<section class="dashboard-panel"><div class="panel-title"><h2>أحدث الطلبات</h2><a href="#admin/orders">عرض جميع الطلبات ${icon('arrow')}</a></div>${adminOrdersTable(5)}</section><section class="dashboard-panel"><div class="panel-title"><h2>المنتجات والمخزون</h2><a href="#admin/products">عرض جميع المنتجات ${icon('arrow')}</a></div>${inventoryTable(4)}</section>`;
return `<div class="admin-shell"><aside class="admin-sidebar"><a href="#home" class="admin-brand">${esc(settings.name)} <span>✦</span><small>لوحة إدارة المتجر</small></a><div class="admin-nav">${[['','home','الرئيسية'],['products','bag','المنتجات'],['orders','box','الطلبات'],['media','image','مكتبة الصور'],['catalogue','box','التشكيلات'],['clients','orders','العملاء والحسابات'],['settings','settings','الإعدادات']].map(([id,ico,label])=>`<a class="${(tab||'')===id?'active':''}" href="#admin${id?'/'+id:''}">${icon(ico)}${label}</a>`).join('')}</div><div class="sidebar-promo"><div class="promo-image">${mediaImage('admin-promo','تشكيلة العبايات')}<button class="image-edit-bubble" aria-label="تعديل صورة لوحة الإدارة" onclick="editImage('admin-promo')">${icon('edit')}</button></div><strong>أضيفي قطعة جديدة</strong><p>وسّعي تشكيلتك بتصاميم<br>تعكس هوية متجرك.</p><button class="button full" onclick="editProduct()">${icon('plus')} إضافة منتج</button></div><a class="back-store" href="#home">${icon('arrow')} زيارة المتجر</a></aside><div class="admin-main"><div class="admin-topbar"><form class="admin-search" onsubmit="event.preventDefault();adminQuery=this.elements.q.value.trim();pageNumbers={};render(false)">${icon('search')}<input name="q" placeholder="ابحثي عن منتج، عميل أو رقم طلب…" value="${esc(adminQuery)}"><button type="submit">بحث</button>${adminQuery?'<button type="button" onclick="adminQuery=\'\';render(false)">مسح</button>':''}</form><div class="admin-user"><a class="notification-button" aria-label="عرض الطلبات الجديدة" href="#admin/orders" onclick="orderFilter='جديد'">${icon('bell')}${orders.filter(o=>o.status==='جديد').length?`<b>${orders.filter(o=>o.status==='جديد').length}</b>`:''}</a><span class="user-avatar">م</span><span>مدير المتجر<small>مساحة الإدارة · معاينة</small></span><button class="text-button" onclick="signOutAccount()">خروج</button></div></div><div class="admin-content">${body}<div class="admin-footer"><span>ديمو تفاعلي · البيانات والصور محفوظة على هذا المتصفح</span><a href="#home">${esc(settings.name)} © ٢٠٢٦</a></div></div></div></div>`}
function editProduct(id){let p=products.find(x=>x.id===id)||{name:'',price:399,stock:10,category:'black',desc:''};modal(`<h2>${id?'تعديل المنتج':'منتج جديد'}</h2>${id?`<div class="product-edit-cover"><div>${mediaImage('product-'+id,p.name)}</div><button type="button" class="button outline" onclick="manageGallery(${id})">${icon('image')} إدارة صور المنتج</button></div>`:'<p class="muted">بعد حفظ المنتج يمكنك تغيير صورته وإضافة معرض صور.</p>'}<form onsubmit="saveProduct(event,${id||0})"><label class="field">اسم المنتج<input name="name" required maxlength="70" value="${esc(p.name)}"></label><div class="form-two"><label class="field">السعر بالريال<input name="price" type="number" min="1" step="0.01" required value="${p.price}"></label><label class="field">الكمية المتاحة<input name="stock" type="number" min="0" step="1" required value="${p.stock}"></label></div><label class="field">التشكيلة<select name="category">${collectionOptions(p.category)}</select></label><fieldset style="border:0;padding:0;margin:18px 0"><legend class="field">المقاسات المتاحة لهذا المنتج</legend><div class="size-checkboxes">${[...new Set(['S','M','L','XL','XXL',...productSizes(p)])].map(s=>`<label><input type="checkbox" name="sizes" value="${esc(s)}" ${productSizes(p).includes(s)?'checked':''}>${esc(s)}</label>`).join('')}</div><label class="field">مقاسات إضافية<input name="customSizes" placeholder="مثال: 52، 54، مقاس موحد" maxlength="200"></label><p class="muted">افصلي المقاسات بفاصلة. الكمية المتاحة هي إجمالي مخزون المنتج.</p></fieldset><label class="field">الوصف<textarea name="desc" required maxlength="600">${esc(p.desc)}</textarea></label><button class="button full">حفظ المنتج</button></form>`)}
function addSampleOrders(){if(orders.some(o=>o.sample)){toast('الطلبات التجريبية موجودة بالفعل');return}const names=['سارة محمد','نورة عبدالله','هند خالد','ريم سعود','فاطمة علي'];names.forEach((name,i)=>{const p=products[i%products.length];orders.push({id:'DEMO-'+(10045-i),sample:true,name,phone:'0500000000',address:'عنوان تجريبي',city:['الرياض','جدة','الدمام'][i%3],total:p.price,status:statuses[i%4],createdAt:Date.now()-i*86400000,date:new Date(Date.now()-i*86400000).toLocaleDateString('ar-SA'),items:[{id:p.id,name:p.name,size:'M',qty:1,price:p.price}]})});save();render(false);toast('تمت إضافة ٥ طلبات للعرض فقط')}
const originalSetStatus=setStatus;
setStatus=function(id,s){const o=orders.find(o=>o.id===id);if(o?.sample){o.status=s;save();render(false);toast('تم تحديث الطلب التجريبي')}else originalSetStatus(id,s)};
function init(){if(!products.length){toast('أضيفي منتجًا للبدء')}$('#search').addEventListener('input',e=>{query=e.target.value.trim();pageNumbers.shop=1;if(!location.hash.startsWith('#shop'))location.hash='shop';else render(false)});window.addEventListener('hashchange',()=>{size='M';qty=1;selectedGallery=0;pageNumbers={};render()});render();if(mediaStorageError)toast('حفظ الصور غير متاح في هذا المتصفح. جرّبي متصفحًا آخر.')}
openMediaDb().then(init).catch(()=>{mediaStorageError=true;init()});
